CREATE OR REPLACE FUNCTION ball_knower_private.assign_player_provider_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  mapped ball_knower_private.player_provider_identities%rowtype;
  catalog record;
  catalog_found boolean := false;
  catalog_match_count integer := 0;
  normalized_row_name text :=
    ball_knower_private.normalized_player_identity_name(new.player_name);
  normalized_row_team text := case upper(coalesce(new.team, ''))
    when 'LA' then 'LAR'
    when 'WSH' then 'WAS'
    when 'JAC' then 'JAX'
    else upper(coalesce(new.team, ''))
  end;
begin
  select * into mapped
  from ball_knower_private.player_provider_identities identity
  where identity.provider_player_id = new.provider_player_id;

  if found then
    if new.ball_knower_player_id is not null
       and new.ball_knower_player_id <> mapped.ball_knower_player_id then
      raise exception 'Provider player % is already bound to a different Ball Knower player', new.provider_player_id;
    end if;
    new.ball_knower_player_id := mapped.ball_knower_player_id;
    new.position := mapped.position;
    return new;
  end if;

  if new.ball_knower_player_id is null then
    return new;
  end if;

  if new.provider_player_id like 'DST:%' then
    if new.ball_knower_player_id <> 'dst-' || lower(split_part(new.provider_player_id, ':', 2))
       or normalized_row_team <> upper(split_part(new.provider_player_id, ':', 2)) then
      raise exception 'D/ST provider identity does not match its Ball Knower team identity';
    end if;
    new.position := 'DST';
  else
    select
      player.player_json ->> 'name' as player_name,
      player.player_json ->> 'team' as team,
      player.player_json ->> 'position' as position
    into catalog
    from ball_knower_private.draft_order_game_players player
    where player.player_id = new.ball_knower_player_id
      and player.active
    limit 1;
    catalog_found := found;

    select count(*)
    into catalog_match_count
    from ball_knower_private.draft_order_game_players player
    where player.active
      and ball_knower_private.normalized_player_identity_name(
        player.player_json ->> 'name'
      ) = normalized_row_name
      and (case upper(coalesce(player.player_json ->> 'team', ''))
             when 'LA' then 'LAR'
             when 'WSH' then 'WAS'
             when 'JAC' then 'JAX'
             else upper(coalesce(player.player_json ->> 'team', ''))
           end) = normalized_row_team;

    if not catalog_found
       or ball_knower_private.normalized_player_identity_name(
            catalog.player_name
          ) <> normalized_row_name
       or (case upper(coalesce(catalog.team, ''))
             when 'LA' then 'LAR'
             when 'WSH' then 'WAS'
             when 'JAC' then 'JAX'
             else upper(coalesce(catalog.team, ''))
           end) <> normalized_row_team
       or catalog_match_count <> 1 then
      raise exception 'Unverified or ambiguous provider identity for Ball Knower player %', new.ball_knower_player_id;
    end if;
    new.position := catalog.position;
  end if;

  insert into ball_knower_private.player_provider_identities(
    provider_player_id,
    ball_knower_player_id,
    canonical_name,
    position,
    match_method
  ) values (
    new.provider_player_id,
    new.ball_knower_player_id,
    new.player_name,
    new.position,
    'live_catalog_identity'
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION ball_knower_private.audit_commissioner_trade_review()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event_type text;
  v_message text;
begin
  if auth.uid() is null
     or coalesce(current_setting('ball_knower.authorized_trade_vote', true), '') = 'approved'
     or not public.is_ball_knower_commissioner(new.league_id)
  then
    return new;
  end if;

  if old.status = 'accepted_pending_review' and new.status = 'accepted' then
    v_event_type := 'commissioner_trade_approved';
    v_message := 'Commissioner approved a pending trade.';
  elsif old.status in ('pending', 'accepted_pending_review') and new.status = 'vetoed' then
    v_event_type := 'commissioner_trade_vetoed';
    v_message := 'Commissioner vetoed a trade.';
  else
    return new;
  end if;

  insert into public.ball_knower_league_events(
    league_id, actor_auth_id, actor_name, event_type, message, metadata
  )
  select new.league_id,
         auth.uid(),
         league.commissioner_name,
         v_event_type,
         v_message,
         jsonb_build_object(
           'tradeId', new.id,
           'previousStatus', old.status,
           'newStatus', new.status
         )
    from public.ball_knower_leagues league
   where league.id = new.league_id;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION ball_knower_private.build_fantasy_regular_schedule(p_member_ids jsonb, p_weeks integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare rotation text[];member_count integer;week_no integer;round_no integer;step integer;slot integer;first_id text;second_id text;home_id text;away_id text;games jsonb:='[]'::jsonb;
begin
  if jsonb_typeof(p_member_ids)<>'array' then return games;end if;
  select array_agg(value order by ordinality) into rotation from jsonb_array_elements_text(p_member_ids) with ordinality;
  member_count:=coalesce(array_length(rotation,1),0);if member_count<2 or mod(member_count,2)<>0 then return games;end if;
  for week_no in 1..greatest(1,p_weeks) loop
    select array_agg(value order by ordinality) into rotation from jsonb_array_elements_text(p_member_ids) with ordinality;
    round_no:=mod(week_no-1,member_count-1);
    for step in 1..round_no loop rotation:=array_cat(array[rotation[1],rotation[member_count]],rotation[2:member_count-1]);end loop;
    for slot in 1..member_count/2 loop
      first_id:=rotation[slot];second_id:=rotation[member_count+1-slot];
      if (mod(round_no,2)=0)<>(mod((week_no-1)/(member_count-1),2)=1) then home_id:=first_id;away_id:=second_id;else home_id:=second_id;away_id:=first_id;end if;
      games:=games||jsonb_build_array(jsonb_build_object('id','game-w'||week_no||'-'||home_id||'-vs-'||away_id,'week',week_no,'homeMemberId',home_id,'awayMemberId',away_id,'homeScore',0,'awayScore',0,'winnerId','','loserId','','isTie',false,'keyMatchupFactor','Scheduled fantasy matchup.'));
    end loop;
  end loop;return games;
end;$function$

CREATE OR REPLACE FUNCTION ball_knower_private.enforce_community_message_safety()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=(select auth.uid()); sender_id uuid; other_id uuid; a uuid; b uuid; league text;
begin
  if tg_table_name='ball_knower_league_messages' then
    sender_id:=new.auth_user_id;
    league:=new.league_id;
  elsif tg_table_name='ball_knower_dm_messages' then
    sender_id:=new.sender_auth_id;
    select t.participant_a,t.participant_b,t.league_id into a,b,league
      from public.ball_knower_dm_threads t where t.id=new.thread_id;
    if sender_id is distinct from a and sender_id is distinct from b then raise exception 'Private thread access denied'; end if;
    other_id:=case when sender_id=a then b else a end;
  elsif tg_table_name='ball_knower_trade_messages' then
    sender_id:=new.sender_auth_id;
    select p.auth_user_id,r.auth_user_id,t.league_id into a,b,league
      from public.ball_knower_trades t
      join public.ball_knower_league_members p on p.id=t.proposer_member_id
      join public.ball_knower_league_members r on r.id=t.recipient_member_id
      where t.id=new.trade_id;
    if sender_id is distinct from a and sender_id is distinct from b then raise exception 'Trade thread access denied'; end if;
    other_id:=case when sender_id=a then b else a end;
  else raise exception 'Unexpected community message table'; end if;
  -- Background system receipts have no human author; preserve them.
  if sender_id is null and me is null and tg_table_name='ball_knower_league_messages' then return new; end if;
  if me is not null and sender_id is distinct from me then raise exception 'Message author does not match signed-in user'; end if;
  if sender_id is null or not exists(select 1 from public.ball_knower_league_members m
    where m.league_id=league and m.auth_user_id=sender_id and not m.is_ai) then
    raise exception 'Current league membership required';
  end if;
  if exists(select 1 from ball_knower_private.community_suspensions where auth_user_id=sender_id and expires_at>now()) then
    raise exception 'Community messaging is suspended; contact support';
  end if;
  if (tg_op='INSERT' or new.body is distinct from old.body) and not ball_knower_private.community_text_allowed(new.body) then
    raise exception 'Message cannot be posted. Follow the community guidelines.';
  end if;
  if other_id is not null then
    perform ball_knower_private.community_pair_lock(sender_id,other_id);
    if exists(select 1 from public.ball_knower_user_blocks
      where (blocker_id=sender_id and blocked_id=other_id) or (blocker_id=other_id and blocked_id=sender_id)) then
      raise exception 'Messaging is not available between these managers';
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION ball_knower_private.enforce_fantasy_acquisition_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb;season_no integer;week_no integer;weekly_limit integer;season_limit integer;weekly_used integer;season_used integer;
begin
  if new.transaction_type not in('waiver','free_agent') then return new;end if;
  select settings into s from public.ball_knower_leagues where id=new.league_id for update;
  season_no:=coalesce(nullif(s->>'nflSeason','')::integer,extract(year from now())::integer);
  week_no:=greatest(1,coalesce(nullif(s->>'currentWeek','')::integer,1));
  weekly_limit:=coalesce(nullif(s->>'maxAcquisitionsPerWeek','')::integer,0);
  season_limit:=coalesce(nullif(s->>'maxAcquisitionsPerSeason','')::integer,0);
  select coalesce(count,0) into weekly_used from ball_knower_private.fantasy_acquisition_counters where league_id=new.league_id and member_id=new.member_id and season=season_no and week=week_no for update;
  select coalesce(sum(count),0) into season_used from ball_knower_private.fantasy_acquisition_counters where league_id=new.league_id and member_id=new.member_id and season=season_no;
  if weekly_limit>0 and coalesce(weekly_used,0)>=weekly_limit then raise exception 'Weekly acquisition limit reached';end if;
  if season_limit>0 and season_used>=season_limit then raise exception 'Season acquisition limit reached';end if;
  insert into ball_knower_private.fantasy_acquisition_counters(league_id,member_id,season,week,count) values(new.league_id,new.member_id,season_no,week_no,1)
  on conflict(league_id,member_id,season,week) do update set count=ball_knower_private.fantasy_acquisition_counters.count+1;
  return new;
end;$function$

CREATE OR REPLACE FUNCTION ball_knower_private.enforce_fantasy_trade_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb;week_no integer;deadline integer;
begin
  select settings into s from public.ball_knower_leagues where id=new.league_id;
  week_no:=greatest(1,coalesce(nullif(s->>'currentWeek','')::integer,1));deadline:=coalesce(nullif(s->>'tradeDeadlineWeek','')::integer,11);
  if week_no>deadline then
    if tg_op='INSERT' then raise exception 'The Week % trade deadline has passed',deadline;
    elsif tg_op='UPDATE' and old.status is distinct from new.status and new.status in('accepted_pending_review','accepted') then raise exception 'The Week % trade deadline has passed',deadline;end if;
  end if;
  return new;
end;$function$

CREATE OR REPLACE FUNCTION ball_knower_private.fantasy_notification_fanout()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  u uuid;
  league text;
  next_member text;
  pick jsonb;
  watcher record;
  new_row jsonb := to_jsonb(new);
  old_row jsonb := '{}'::jsonb;
  member_count integer;
  next_pick_index integer;
begin
  if tg_op = 'UPDATE' then
    old_row := to_jsonb(old);
  end if;

  if tg_table_name = 'ball_knower_trades' then
    league := new_row ->> 'league_id';
    select auth_user_id
      into u
      from public.ball_knower_league_members
     where id = case
       when tg_op = 'INSERT' then new_row ->> 'recipient_member_id'
       when new_row ->> 'status' in ('rejected', 'vetoed', 'accepted', 'accepted_pending_review')
         then new_row ->> 'proposer_member_id'
       else new_row ->> 'recipient_member_id'
     end;

    perform ball_knower_private.notify_fantasy_user(
      league,
      u,
      case
        when tg_op = 'INSERT' then 'Trade received'
        else 'Trade ' || replace(new_row ->> 'status', '_', ' ')
      end,
      'Open League Activity for the latest trade update.',
      'trade_' || (new_row ->> 'status')
    );
  elsif tg_table_name = 'ball_knower_waiver_claims' then
    if (old_row ->> 'status') is distinct from (new_row ->> 'status')
       and (new_row ->> 'status') in ('won', 'lost') then
      select league_id, auth_user_id
        into league, u
        from public.ball_knower_league_members
       where id = new_row ->> 'member_id';

      perform ball_knower_private.notify_fantasy_user(
        league,
        u,
        'Waiver ' || (new_row ->> 'status'),
        coalesce(new_row #>> '{player_snapshot,name}', new_row ->> 'player_id')
          || ' · ' || coalesce(new_row ->> 'failure_reason', 'Claim processed'),
        'waiver_' || (new_row ->> 'status')
      );
    end if;
  elsif tg_table_name = 'ball_knower_injuries' then
    select m.league_id, m.auth_user_id
      into league, u
      from public.ball_knower_league_members m
     where m.id = new_row ->> 'member_id';

    perform ball_knower_private.notify_fantasy_user(
      league,
      u,
      'Player status update',
      (new_row ->> 'player_name') || ' is now ' || (new_row ->> 'status') || '.',
      'player_status'
    );
  elsif tg_table_name = 'ball_knower_live_drafts' then
    if (new_row ->> 'status') <> 'active' then
      return new;
    end if;

    if tg_op = 'UPDATE'
       and (old_row ->> 'pick_index') is not distinct from (new_row ->> 'pick_index') then
      return new;
    end if;

    if jsonb_typeof(new_row -> 'order_member_ids') <> 'array' then
      return new;
    end if;

    member_count := jsonb_array_length(new_row -> 'order_member_ids');
    if member_count = 0 then
      return new;
    end if;

    next_pick_index := coalesce((new_row ->> 'pick_index')::integer, 0);
    next_member := new_row -> 'order_member_ids' ->> (
      case
        when mod(next_pick_index / member_count, 2) = 0
          then mod(next_pick_index, member_count)
        else member_count - 1 - mod(next_pick_index, member_count)
      end
    );

    select auth_user_id
      into u
      from public.ball_knower_league_members
     where league_id = new_row ->> 'league_id'
       and id = next_member;

    perform ball_knower_private.notify_fantasy_user(
      new_row ->> 'league_id',
      u,
      'You are on the clock',
      'Your Ball Knower fantasy pick is ready.',
      'draft_on_clock'
    );

    if tg_op = 'UPDATE'
       and jsonb_typeof(new_row -> 'picks') = 'array'
       and jsonb_array_length(new_row -> 'picks') > 0 then
      pick := new_row -> 'picks' -> -1;
      if pick ->> 'source' = 'autopick' then
        select auth_user_id
          into u
          from public.ball_knower_league_members
         where league_id = new_row ->> 'league_id'
           and id = pick ->> 'memberId';

        perform ball_knower_private.notify_fantasy_user(
          new_row ->> 'league_id',
          u,
          'Selection autopicked',
          'Your queue or best available player made the pick.',
          'draft_autopick'
        );
      end if;
    end if;
  elsif tg_table_name = 'ball_knower_league_messages' then
    for watcher in
      select auth_user_id
        from public.ball_knower_league_members
       where league_id = new_row ->> 'league_id'
         and auth_user_id is not null
         and auth_user_id <> (new_row ->> 'auth_user_id')::uuid
         and not is_ai
    loop
      perform ball_knower_private.notify_fantasy_user(
        new_row ->> 'league_id',
        watcher.auth_user_id,
        'League message',
        (new_row ->> 'member_name') || ': ' || left(new_row ->> 'body', 180),
        'league_message'
      );
    end loop;
  elsif tg_table_name = 'ball_knower_trading_block' then
    for watcher in
      select watched.auth_user_id
        from public.ball_knower_watched_players watched
       where watched.league_id = new_row ->> 'league_id'
         and watched.player_id = new_row ->> 'player_id'
         and exists (
           select 1
             from public.ball_knower_league_members m
            where m.league_id = new_row ->> 'league_id'
              and m.auth_user_id = watched.auth_user_id
              and not m.is_ai
         )
    loop
      perform ball_knower_private.notify_fantasy_user(
        new_row ->> 'league_id',
        watcher.auth_user_id,
        'Watched player on Trading Block',
        (new_row ->> 'player_id') || ' is marked '
          || replace(new_row ->> 'status', '_', ' ') || '.',
        'trading_block'
      );
    end loop;
  elsif tg_table_name = 'ball_knower_weekly_scores' then
    if not coalesce((new_row ->> 'is_final')::boolean, false) then
      return new;
    end if;

    if tg_op = 'UPDATE'
       and coalesce((old_row ->> 'is_final')::boolean, false) then
      return new;
    end if;

    select auth_user_id
      into u
      from public.ball_knower_league_members
     where id = new_row ->> 'member_id';

    perform ball_knower_private.notify_fantasy_user(
      new_row ->> 'league_id',
      u,
      'Final matchup result',
      'Your Week ' || (new_row ->> 'week_number') || ' score is final: '
        || (new_row ->> 'live_points') || ' points.',
      'matchup_final'
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION ball_knower_private.fantasy_player_payload(p_player_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'ball_knower_private', 'pg_temp'
AS $function$
declare
  v_group text;
  v_payload jsonb;
  v_team text;
  v_dst_ovr integer;
begin
  select g.draft_group,p.player_json into v_group,v_payload
  from public.ball_knower_fantasy_player_groups g
  left join ball_knower_private.draft_order_game_players p on p.player_id=g.player_id
  where g.player_id=p_player_id;
  if v_group is null then raise exception 'Unknown fantasy player id %',p_player_id; end if;
  if v_group not in ('QB','RB','WR','TE','K','DST') then raise exception 'Invalid fantasy player group %',v_group; end if;
  if v_payload is not null then return v_payload||jsonb_build_object('position',v_group,'positionGroup',v_group); end if;
  if v_group<>'DST' then raise exception 'Canonical fantasy player data is missing for %',p_player_id; end if;
  v_team:=upper(split_part(p_player_id,'-',2));
  if nullif(v_team,'') is null then raise exception 'Invalid D/ST id %',p_player_id; end if;
  select coalesce(round(avg(defender_ovr))::integer,70) into v_dst_ovr
  from (
    select (p.player_json->>'ovr')::numeric as defender_ovr
    from ball_knower_private.draft_order_game_players p
    where upper(p.player_json->>'team')=v_team
      and upper(p.player_json->>'position') in ('EDGE','DE','DT','DL','LB','MLB','OLB','CB','FS','SS','S')
      and (p.player_json->>'ovr') ~ '^[0-9]+([.][0-9]+)?$'
    order by (p.player_json->>'ovr')::numeric desc limit 11
  ) defense;
  v_dst_ovr:=greatest(60,least(99,coalesce(v_dst_ovr,70)));
  return jsonb_build_object('id',p_player_id,'playerId',p_player_id,'name',v_team||' D/ST','team',v_team,'teamId',v_team,'position','DST','positionGroup','DST','ovr',v_dst_ovr,'overall',v_dst_ovr,'overallRating',v_dst_ovr,'ratingSource','Ball Knower Composite','ratingSeason',2026,'ratingStatus','VERIFIED','rosterSeason',2026,'active',true,'isFreeAgent',false);
end;
$function$

CREATE OR REPLACE FUNCTION ball_knower_private.fantasy_team_ratings_from_roster(p_roster jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'ball_knower_private', 'pg_temp'
AS $function$
declare
  v_qb numeric:=65;v_rb numeric:=65;v_wr numeric:=65;v_te numeric:=65;v_flex numeric:=65;
  v_k numeric:=60;v_dst numeric:=60;v_depth numeric:=65;
  v_offense integer;v_defense integer;v_overall integer;v_balance integer;v_efficiency integer;
  v_min_group numeric;v_max_group numeric;v_spread numeric:=30;
  v_penalties text[]:=array[]::text[];v_strengths text[]:=array[]::text[];
begin
  if jsonb_typeof(p_roster)<>'array' or jsonb_array_length(p_roster)<1 then raise exception 'Fantasy roster is empty'; end if;
  select coalesce(avg(ovr),65) into v_qb from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x where x->>'position'='QB' order by 1 desc limit 1) s;
  select coalesce(avg(ovr),65) into v_rb from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x where x->>'position'='RB' order by 1 desc limit 2) s;
  select coalesce(avg(ovr),65) into v_wr from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x where x->>'position'='WR' order by 1 desc limit 3) s;
  select coalesce(avg(ovr),65) into v_te from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x where x->>'position'='TE' order by 1 desc limit 1) s;
  select coalesce(avg(ovr),65) into v_flex from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x where x->>'position' in ('RB','WR','TE') order by 1 desc limit 6) s;
  select coalesce(avg(ovr),60) into v_k from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x where x->>'position'='K' order by 1 desc limit 1) s;
  select coalesce(avg(ovr),60) into v_dst from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x where x->>'position'='DST' order by 1 desc limit 1) s;
  select coalesce(avg(ovr),65) into v_depth from (select (x->>'ovr')::numeric ovr from jsonb_array_elements(p_roster) x order by 1 desc limit 12) s;
  v_offense:=greatest(40,least(99,round(v_qb*.24+v_rb*.22+v_wr*.27+v_te*.10+v_flex*.12+v_depth*.05)::integer));
  v_defense:=greatest(40,least(99,round(v_dst*.72+v_k*.08+v_depth*.20)::integer));
  v_overall:=greatest(40,least(99,round(v_offense*.78+v_defense*.10+v_depth*.12)::integer));
  select min(group_avg),max(group_avg) into v_min_group,v_max_group from (
    select avg(ovr) group_avg from (
      select x->>'position' position,(x->>'ovr')::numeric ovr,row_number() over(partition by x->>'position' order by (x->>'ovr')::numeric desc) rn
      from jsonb_array_elements(p_roster) x where x->>'position' in ('QB','RB','WR','TE','K','DST')
    ) ranked where rn<=2 group by position
  ) groups;
  if v_min_group is not null and v_max_group is not null then v_spread:=v_max_group-v_min_group; end if;
  v_balance:=greatest(40,least(99,round(100-v_spread*1.8)::integer));
  v_efficiency:=greatest(40,least(99,round(v_overall*.7+v_balance*.3)::integer));
  if not exists(select 1 from jsonb_array_elements(p_roster) x where x->>'position'='QB') then v_penalties:=array_append(v_penalties,'No quarterback'); end if;
  if (select count(*) from jsonb_array_elements(p_roster) x where x->>'position'='RB')<2 then v_penalties:=array_append(v_penalties,'Thin running back room'); end if;
  if (select count(*) from jsonb_array_elements(p_roster) x where x->>'position'='WR')<3 then v_penalties:=array_append(v_penalties,'Thin wide receiver room'); end if;
  if not exists(select 1 from jsonb_array_elements(p_roster) x where x->>'position'='TE') then v_penalties:=array_append(v_penalties,'No tight end'); end if;
  if not exists(select 1 from jsonb_array_elements(p_roster) x where x->>'position'='K') then v_penalties:=array_append(v_penalties,'No kicker'); end if;
  if not exists(select 1 from jsonb_array_elements(p_roster) x where x->>'position'='DST') then v_penalties:=array_append(v_penalties,'No D/ST'); end if;
  if v_qb>=85 then v_strengths:=array_append(v_strengths,'Elite quarterback ceiling'); end if;
  if v_rb>=84 then v_strengths:=array_append(v_strengths,'High-end running backs'); end if;
  if v_wr>=84 then v_strengths:=array_append(v_strengths,'Deep receiving corps'); end if;
  if v_depth>=82 then v_strengths:=array_append(v_strengths,'Strong fantasy depth'); end if;
  return jsonb_build_object('overall',v_overall,'offense',v_offense,'defense',v_defense,'passing',greatest(40,least(99,round(v_qb*.55+v_wr*.32+v_te*.13)::integer)),'rushing',greatest(40,least(99,round(v_rb*.78+v_flex*.22)::integer)),'passProtection',greatest(40,least(99,round(v_depth)::integer)),'runBlocking',greatest(40,least(99,round(v_flex)::integer)),'passRush',greatest(40,least(99,round(v_dst)::integer)),'runDefense',greatest(40,least(99,round(v_dst)::integer)),'coverage',greatest(40,least(99,round(v_dst)::integer)),'balanceScore',v_balance,'efficiencyRating',v_efficiency,'penalties',to_jsonb(v_penalties),'strengths',to_jsonb(v_strengths));
end;
$function$

CREATE OR REPLACE FUNCTION ball_knower_private.finalize_completed_live_draft(p_league_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_draft public.ball_knower_live_drafts%rowtype;
  v_league public.ball_knower_leagues%rowtype;
  v_member public.ball_knower_league_members%rowtype;
  v_roster jsonb;
  v_ratings jsonb;
  v_member_count integer;
  v_weeks integer;
  v_schedule jsonb;
  v_result jsonb;
  v_existing_games jsonb;
begin
  select * into v_draft
  from public.ball_knower_live_drafts
  where league_id = p_league_id
  for update;
  if not found then
    raise exception 'Fantasy draft has not started';
  end if;
  if v_draft.status <> 'completed'
     or v_draft.pick_index <> jsonb_array_length(v_draft.order_member_ids) * v_draft.rounds
     or jsonb_array_length(v_draft.picks) <> v_draft.pick_index
  then
    raise exception 'Fantasy draft is not complete';
  end if;

  select * into v_league
  from public.ball_knower_leagues
  where id = p_league_id
  for update;
  if not found then
    raise exception 'League not found';
  end if;

  select count(*) into v_member_count
  from public.ball_knower_league_members
  where league_id = p_league_id;
  if v_member_count <> jsonb_array_length(v_draft.order_member_ids) then
    raise exception 'Draft order no longer matches league membership';
  end if;

  -- Public callers may safely retry finalization after a timeout. Once every
  -- finalized roster is present, preserve all later season and schedule work.
  if v_league.rosters_locked
     and not exists (
       select 1
       from public.ball_knower_league_members member
       where member.league_id = p_league_id
         and (
           member.status <> 'ready'
           or jsonb_array_length(coalesce(member.roster, '[]'::jsonb)) <> v_draft.rounds
         )
     )
  then
    return true;
  end if;

  perform set_config('ball_knower.authorized_roster_operation', 'system', true);
  for v_member in
    select *
    from public.ball_knower_league_members
    where league_id = p_league_id
    for update
  loop
    select jsonb_agg(
      ball_knower_private.fantasy_player_payload(pick->>'playerId')
      order by (pick->>'overall')::integer
    )
    into v_roster
    from jsonb_array_elements(v_draft.picks) pick
    where pick->>'memberId' = v_member.id;

    if jsonb_typeof(v_roster) <> 'array'
       or jsonb_array_length(v_roster) <> v_draft.rounds
    then
      raise exception 'Every completed fantasy roster must contain exactly % canonical players', v_draft.rounds;
    end if;
    if (
      select count(distinct player->>'id')
      from jsonb_array_elements(v_roster) player
    ) <> v_draft.rounds
    then
      raise exception 'A completed fantasy roster contains duplicate players';
    end if;

    v_ratings := ball_knower_private.fantasy_team_ratings_from_roster(v_roster);
    update public.ball_knower_league_members
    set roster = v_roster,
        team_ratings = v_ratings,
        status = 'ready',
        submitted_at = coalesce(v_draft.completed_at, clock_timestamp())
    where league_id = p_league_id
      and id = v_member.id;
  end loop;

  v_weeks := least(
    17,
    greatest(
      1,
      coalesce(
        nullif(v_league.settings->>'regularSeasonWeeks', '')::integer,
        nullif(v_league.settings->>'seasonGames', '')::integer,
        17
      )
    )
  );
  v_schedule := ball_knower_private.build_fantasy_regular_schedule(
    v_draft.order_member_ids,
    v_weeks
  );

  if jsonb_array_length(v_schedule) <> v_weeks * v_member_count / 2 then
    raise exception 'Completed draft could not create a complete fantasy schedule';
  end if;

  v_result := coalesce(v_league.season_result, '{}'::jsonb);
  v_existing_games := coalesce(v_result->'games', '[]'::jsonb);
  if coalesce(v_result->>'orderMethod', '') = 'game'
     and jsonb_array_length(v_existing_games) > 0
     and not (v_result ? 'draftOrderGameGames')
  then
    v_result := jsonb_set(
      v_result,
      '{draftOrderGameGames}',
      v_existing_games,
      true
    );
  end if;
  v_result := jsonb_set(v_result, '{games}', v_schedule, true);

  update public.ball_knower_leagues
  set status = 'drafting',
      rosters_locked = true,
      season_result = v_result,
      updated_at = clock_timestamp()
  where id = p_league_id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION ball_knower_private.finalize_live_draft_after_last_pick()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    perform ball_knower_private.finalize_completed_live_draft(new.league_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION ball_knower_private.require_permanent_community_user()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid := (select auth.uid());
begin
  if me is null or not exists(select 1 from auth.users u where u.id=me and not coalesce(u.is_anonymous,false)) then
    raise exception 'Save or sign in to your Ball Knower account to use Community';
  end if;
  if exists(select 1 from ball_knower_private.community_suspensions s where s.auth_user_id=me and s.expires_at>now()) then
    raise exception 'Community access is suspended; contact Ball Knower support';
  end if;
  return me;
end $function$

CREATE OR REPLACE FUNCTION ball_knower_private.validate_fantasy_league_settings()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s jsonb:=coalesce(new.settings,'{}'::jsonb);v integer;regular_weeks integer;playoff_count integer;score record;
begin
  if coalesce(s->>'scoringFormat','ppr') not in ('ppr','half_ppr','standard') then raise exception 'Invalid scoring format'; end if;
  if coalesce(s->>'draftFormat','live_snake') not in ('live_snake','autopick','offline','mock','auction') then raise exception 'Invalid draft format'; end if;
  if coalesce(s->>'tradeReview','commissioner') not in ('none','commissioner','league_vote') then raise exception 'Invalid trade review'; end if;
  if coalesce(s->>'waiverType','priority') not in ('priority','faab') then raise exception 'Invalid waiver type'; end if;
  if coalesce(s->>'freeAgentMode','instant') not in ('instant','continuous') then raise exception 'Invalid free-agent mode'; end if;
  if coalesce(s->>'playoffSeeding','record_points') not in ('record_points','record_head_to_head','division_winners') then raise exception 'Invalid playoff seeding'; end if;
  v:=coalesce(nullif(s->>'regularSeasonWeeks','')::integer,nullif(s->>'seasonGames','')::integer,17);if v not between 13 and 17 then raise exception 'Regular season must be 13-17 weeks';end if;regular_weeks:=v;
  v:=coalesce(nullif(s->>'playoffTeams','')::integer,6);if v not in (4,6,8) or v>new.max_members then raise exception 'Playoff field must be 4, 6 or 8 and fit the league';end if;playoff_count:=v;
  if tg_op='INSERT' or (tg_op='UPDATE' and (coalesce(nullif(old.settings->>'regularSeasonWeeks','')::integer,nullif(old.settings->>'seasonGames','')::integer,17)<>regular_weeks or old.settings->'playoffTeams' is distinct from s->'playoffTeams')) then
    if regular_weeks+(case when playoff_count=4 then 2 else 3 end)>18 then raise exception 'Regular season and playoffs must finish by NFL Week 18';end if;
  end if;
  v:=coalesce(nullif(s->>'benchSlots','')::integer,6);if v not between 6 and 11 then raise exception 'Bench slots must be 6-11';end if;
  if coalesce(nullif(s->>'rosterSize','')::integer,9+v)<>9+v then raise exception 'Roster size must equal nine starters plus bench slots';end if;
  v:=coalesce(nullif(s->>'irSlots','')::integer,2);if v not between 0 and 5 then raise exception 'IR slots must be 0-5';end if;
  v:=coalesce(nullif(s->>'waiverProcessHourUtc','')::integer,9);if v not between 0 and 23 then raise exception 'Waiver hour must be 0-23 UTC';end if;
  v:=coalesce(nullif(s->>'tradeDeadlineWeek','')::integer,11);if v not between 1 and 17 then raise exception 'Trade deadline must be Week 1-17';end if;
  v:=coalesce(nullif(s->>'maxAcquisitionsPerWeek','')::integer,0);if v not between 0 and 99 then raise exception 'Weekly acquisition limit must be 1-99 or disabled';end if;
  v:=coalesce(nullif(s->>'maxAcquisitionsPerSeason','')::integer,0);if v not between 0 and 999 then raise exception 'Season acquisition limit must be 1-999 or disabled';end if;
  if coalesce((s->>'divisionsEnabled')::boolean,false) and coalesce(nullif(s->>'divisionCount','')::integer,2) not in(2,4) then raise exception 'Divisions must use two or four groups';end if;
  if jsonb_typeof(coalesce(s->'customScoring','{}'::jsonb))<>'object' then raise exception 'Custom scoring must be an object';end if;
  for score in select key,value from jsonb_each_text(coalesce(s->'customScoring','{}'::jsonb)) loop
    if score.key not in('passYards','passTd','interception','rushYards','rushTd','reception','recYards','recTd','fumbleLost','fieldGoal','extraPoint','dstSack','dstTurnover','dstTd') then raise exception 'Unknown custom scoring category %',score.key;end if;
    if score.value!~'^[-]?[0-9]+([.][0-9]+)?$' or score.value::numeric not between -100 and 100 then raise exception 'Invalid custom scoring value for %',score.key;end if;
  end loop;
  if tg_op='UPDATE' then
    if coalesce(nullif(old.settings->>'regularSeasonWeeks','')::integer,nullif(old.settings->>'seasonGames','')::integer,17)<>coalesce(nullif(s->>'regularSeasonWeeks','')::integer,nullif(s->>'seasonGames','')::integer,17)
      and exists(select 1 from jsonb_array_elements(coalesce(old.season_result->'games','[]'::jsonb)) game where not(game?'playoffRound'))
    then raise exception 'Regular-season length is locked after the schedule is created';end if;
    if coalesce(nullif(old.settings->>'playoffTeams','')::integer,6)<>playoff_count
      and exists(select 1 from jsonb_array_elements(coalesce(old.season_result->'games','[]'::jsonb)) game where not(game?'playoffRound'))
    then raise exception 'Playoff field is locked after the schedule is created';end if;
    if (old.settings->'scoringFormat' is distinct from s->'scoringFormat' or old.settings->'customScoring' is distinct from s->'customScoring')
      and exists(select 1 from public.ball_knower_weekly_scores where league_id=new.id and (is_final or live_points<>0))
    then raise exception 'Scoring settings are locked after scoring begins';end if;
    if (old.settings->'playoffTeams' is distinct from s->'playoffTeams' or old.settings->'playoffSeeding' is distinct from s->'playoffSeeding' or old.settings->'divisionsEnabled' is distinct from s->'divisionsEnabled' or old.settings->'divisionCount' is distinct from s->'divisionCount')
      and (exists(select 1 from public.ball_knower_weekly_scores where league_id=new.id and week_number>coalesce(nullif(old.settings->>'regularSeasonWeeks','')::integer,nullif(old.settings->>'seasonGames','')::integer,17) and (is_final or live_points<>0))
        or exists(select 1 from jsonb_array_elements(coalesce(old.season_result->'games','[]'::jsonb)) game where game?'playoffRound' and (coalesce(game->>'winnerId','')<>'' or coalesce(nullif(game->>'homeScore','')::numeric,0)<>0 or coalesce(nullif(game->>'awayScore','')::numeric,0)<>0)))
    then raise exception 'Playoff field and seeding are locked after postseason scoring begins';end if;
  end if;
  return new;
end;$function$

CREATE OR REPLACE FUNCTION bk_football_private.arena_api(p_action text, p_args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=ball_knower_private.require_permanent_community_user();
 m bk_football_private.matches%rowtype; d bk_football_private.drives%rowtype;
 opponent uuid; mid uuid; team text; n integer; pts integer; yds integer; snaps integer; stats jsonb; details jsonb; result jsonb; standings jsonb; cleanup record;
begin
 if p_args is null or jsonb_typeof(p_args)<>'object' or octet_length(p_args::text)>4096 then raise exception 'Invalid football request'; end if;
 if p_action='home' then
   -- Settle expired attempts and matches without relying on a player's device clock.
   for cleanup in select id from bk_football_private.matches where status='active' and (me in(challenger_id,opponent_id) or expires_at<=now()) order by created_at limit 200 loop
     perform bk_football_private.settle(cleanup.id);
   end loop;
   update bk_football_private.matches set status='expired' where status in('open','pending') and expires_at<=now();
   select coalesce(jsonb_agg(row),'[]'::jsonb) into result from (
     select c.*,coalesce(p.display_name,'Ball Knower') challenger_name,coalesce(q.display_name,'Opponent') opponent_name,
       coalesce((select jsonb_agg(jsonb_build_object('user_id',x.user_id,'ordinal',x.ordinal,'points',x.points,'yards',x.yards,'plays',x.plays,'passingYards',x.offense_stats->'passingYards','rushingYards',x.offense_stats->'rushingYards','passAttempts',x.offense_stats->'passAttempts','completions',x.offense_stats->'completions','touchdowns',x.offense_stats->'touchdowns','turnovers',x.offense_stats->'turnovers','returnTouchdowns',x.offense_stats->'returnTouchdowns','forfeited',x.forfeited,'finished_at',x.finished_at,'deadline',x.deadline) order by x.user_id,x.ordinal) from bk_football_private.drives x where x.match_id=c.id),'[]'::jsonb) drives
     from bk_football_private.matches c left join public.ball_knower_progress_profiles p on p.user_id=c.challenger_id left join public.ball_knower_progress_profiles q on q.user_id=c.opponent_id
     where (me in(c.challenger_id,c.opponent_id) or c.status='open')
       and not exists(select 1 from public.ball_knower_user_blocks b where (b.blocker_id=me and b.blocked_id in(c.challenger_id,c.opponent_id)) or (b.blocked_id=me and b.blocker_id in(c.challenger_id,c.opponent_id)))
       and bk_minigames_private.available(c.challenger_id) and (c.opponent_id is null or bk_minigames_private.available(c.opponent_id))
     order by (c.status='active') desc,c.created_at desc limit 100
   ) row;
   select coalesce(jsonb_agg(row),'[]'::jsonb) into standings from (
     select u.user_id,coalesce(p.display_name,'Ball Knower') name,count(*) games,
       count(*) filter(where c.winner_id=u.user_id) wins,count(*) filter(where c.winner_id is not null and c.winner_id<>u.user_id) losses,count(*) filter(where c.winner_id is null) ties,
       count(*) filter(where c.winner_id=u.user_id)*3+count(*) filter(where c.winner_id is null) rating
     from bk_football_private.matches c cross join lateral unnest(array[c.challenger_id,c.opponent_id]) u(user_id)
     left join public.ball_knower_progress_profiles p on p.user_id=u.user_id
     where c.status='completed' and bk_minigames_private.available(u.user_id)
       and not exists(select 1 from public.ball_knower_user_blocks b where (b.blocker_id=me and b.blocked_id=u.user_id) or (b.blocked_id=me and b.blocker_id=u.user_id))
     group by u.user_id,p.display_name order by rating desc,wins desc,u.user_id limit 50
   ) row;
   return jsonb_build_object('matches',result,'standings',standings);
 end if;
 -- Queue requests take the shared queue lock before the per-user lock. Nested
 -- create/accept calls retain the same order and cannot pair the same open slot.
 if p_action='quick_match' then
   perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bk-football-quick-match',0));
 end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bk-football:'||me::text,0));
 if p_action in('create','accept','quick_match') then
   team:=p_args->>'team';
   if team is null or not team=any(array['ABQ','ANC','AUS','BIR','BOI','BRK','CHS','CLB','DSM','HFD','HNL','JCY','LOU','MEM','MIL','OKC','OMA','ORL','POR','RAL','RIC','RNO','SAC','SLC','SAT','SDG','STL','TOR','VBH','ALB','ELP','FAR']) then raise exception 'Choose a season 1 team'; end if;
 end if;
 if p_action='quick_match' then
   -- Retry lost responses without creating a second match. Friend challenges
   -- are not queue entries and are never silently resumed by quick play.
   select * into m from bk_football_private.matches c where c.matchmaking
     and me in(c.challenger_id,c.opponent_id) and c.status in('open','active') and c.expires_at>now()
     and bk_minigames_private.available(c.challenger_id)
     and (c.opponent_id is null or bk_minigames_private.available(c.opponent_id))
     and not exists(select 1 from public.ball_knower_user_blocks b where
       (b.blocker_id=me and b.blocked_id in(c.challenger_id,c.opponent_id)) or
       (b.blocked_id=me and b.blocker_id in(c.challenger_id,c.opponent_id)))
     order by (c.status='active') desc,c.created_at limit 1;
   if found then return jsonb_build_object('id',m.id,'status',m.status); end if;
   select * into m from bk_football_private.matches c where c.matchmaking
     and c.status='open' and c.expires_at>now() and c.challenger_id<>me
     and bk_minigames_private.available(c.challenger_id)
     and not exists(select 1 from public.ball_knower_user_blocks b where
       (b.blocker_id=me and b.blocked_id=c.challenger_id) or (b.blocked_id=me and b.blocker_id=c.challenger_id))
     order by c.created_at,c.id limit 1 for update;
   if found then
     perform bk_football_private.arena_api('accept',jsonb_build_object('id',m.id,'team',team));
     return jsonb_build_object('id',m.id,'status','active');
   end if;
   result:=bk_football_private.arena_api('create',jsonb_build_object('team',team));
   mid:=(result->>'id')::uuid;
   update bk_football_private.matches set matchmaking=true,expires_at=now()+interval '45 seconds' where id=mid;
   return jsonb_build_object('id',mid,'status','open');
 end if;
 if p_action='create' then
   if (select count(*) from bk_football_private.matches where challenger_id=me and created_at>now()-interval '1 hour')>=20 then raise exception 'Challenge limit reached. Try again later.'; end if;
   if (select count(*) from bk_football_private.matches where me in(challenger_id,opponent_id) and status in('open','pending','active') and expires_at>now())>=5 then raise exception 'Finish or cancel an existing match first'; end if;
   opponent:=(p_args->>'opponent')::uuid;
   if opponent is not null then
     if opponent=me or not exists(select 1 from public.ball_knower_friendships where status='accepted' and (requester_id=me and recipient_id=opponent or requester_id=opponent and recipient_id=me)) then raise exception 'Choose an accepted friend'; end if;
     if not bk_minigames_private.available(opponent) or exists(select 1 from public.ball_knower_user_blocks where (blocker_id=me and blocked_id=opponent) or (blocker_id=opponent and blocked_id=me)) then raise exception 'Opponent is unavailable'; end if;
   end if;
   insert into bk_football_private.matches(challenger_id,opponent_id,challenger_team,status) values(me,opponent,team,case when opponent is null then 'open' else 'pending' end) returning id into mid;
   return jsonb_build_object('id',mid);
 end if;
 mid:=(p_args->>'id')::uuid;
 select * into m from bk_football_private.matches where id=mid for update;
 if not found then raise exception 'Match is unavailable'; end if;
 if exists(select 1 from public.ball_knower_user_blocks b where (b.blocker_id=me and b.blocked_id in(m.challenger_id,m.opponent_id)) or (b.blocked_id=me and b.blocker_id in(m.challenger_id,m.opponent_id))) then raise exception 'Match is unavailable'; end if;
 if not bk_minigames_private.available(m.challenger_id) or (m.opponent_id is not null and not bk_minigames_private.available(m.opponent_id)) then raise exception 'Opponent is unavailable'; end if;
 if p_action='accept' then
   if m.expires_at<=now() or m.status not in('open','pending') or m.challenger_id=me or (m.status='pending' and m.opponent_id<>me) then raise exception 'This challenge cannot be accepted'; end if;
   if (select count(*) from bk_football_private.matches where me in(challenger_id,opponent_id) and status='active' and expires_at>now())>=5 then raise exception 'Finish an active match first'; end if;
   update bk_football_private.matches set opponent_id=me,opponent_team=team,status='active',expires_at=now()+interval '24 hours' where id=mid;
   return jsonb_build_object('id',mid);
 end if;
 if me<>m.challenger_id and me is distinct from m.opponent_id then raise exception 'Match is unavailable'; end if;
 if p_action='cancel' and m.challenger_id=me and m.status in('open','pending') then
   update bk_football_private.matches set status='cancelled' where id=mid;return '{}'::jsonb;
 elsif p_action='decline' and m.opponent_id=me and m.status='pending' then
   update bk_football_private.matches set status='declined' where id=mid;return '{}'::jsonb;
 end if;
 perform bk_football_private.settle(mid);
 select * into m from bk_football_private.matches where id=mid;
 n:=(p_args->>'drive')::integer;
 if n is null or n not between 1 and 3 then raise exception 'Choose drive 1, 2 or 3'; end if;
 select * into d from bk_football_private.drives where match_id=mid and user_id=me and ordinal=n;
 -- Result retries are immutable and require the original attempt token, even after finalization.
 if p_action='submit' and d.finished_at is not null then
   if d.token is distinct from (p_args->>'token')::uuid then raise exception 'Invalid drive token'; end if;
   return jsonb_build_object('saved',true,'points',d.points,'forfeited',d.forfeited);
 end if;
 if p_action='forfeit' and d.finished_at is not null then return jsonb_build_object('saved',true); end if;
 if m.status<>'active' then raise exception 'This match is not active'; end if;
 if p_action='begin' then
   if d.match_id is not null then
     if d.finished_at is not null or d.launch_id is distinct from (p_args->>'launch')::uuid then raise exception 'This drive was already started. Record zero for the interrupted drive to continue.'; end if;
   else
     if n<>(select count(*)+1 from bk_football_private.drives where match_id=mid and user_id=me and finished_at is not null) then raise exception 'Finish the previous drive first'; end if;
     insert into bk_football_private.drives(match_id,user_id,ordinal,launch_id) values(mid,me,n,(p_args->>'launch')::uuid) returning * into d;
   end if;
   return jsonb_build_object('token',d.token,'drive',d.ordinal,'deadline',d.deadline,'seed',(m.seed::bigint+n*104729)%2147483647,'team',case when me=m.challenger_id then m.challenger_team else m.opponent_team end,'opponent',case when me=m.challenger_id then m.opponent_team else m.challenger_team end);
 elsif p_action in('submit','forfeit') then
   if d.match_id is null then raise exception 'Start this drive first'; end if;
   if p_action='forfeit' then pts:=0;yds:=0;snaps:=0;
   else
     if d.token is distinct from (p_args->>'token')::uuid then raise exception 'Invalid drive token'; end if;
     if d.started_at>now()-interval '2 seconds' then raise exception 'Complete your drive before submitting'; end if;
     stats:=p_args->'stats';
     if stats is null or jsonb_typeof(stats)<>'object' or not stats ?& array['points','yards','plays'] or stats-array['points','yards','plays','passingYards','rushingYards','passAttempts','completions','touchdowns','turnovers','returnTouchdowns']<>'{}'::jsonb then raise exception 'Complete drive stats are required'; end if;
     if exists(select 1 from jsonb_each(stats) v where jsonb_typeof(v.value)<>'number' or v.value::text::numeric<>trunc(v.value::text::numeric)) then raise exception 'Drive stats must be whole numbers'; end if;
     details:=stats-array['points','yards','plays'];
     if details<>'{}'::jsonb then
       if not details ?& array['passingYards','rushingYards','passAttempts','completions','touchdowns','turnovers'] then raise exception 'Complete offensive stats are required'; end if;
       if (details->>'passingYards')::numeric not between -200 and 500
         or (details->>'rushingYards')::numeric not between -200 and 500
         or (details->>'passAttempts')::numeric not between 0 and 200
         or (details->>'completions')::numeric not between 0 and (details->>'passAttempts')::numeric
         or (details->>'passAttempts')::numeric>(stats->>'plays')::numeric
         or (details->>'touchdowns')::numeric not between 0 and 1
         or (details->>'turnovers')::numeric not between 0 and 1
         or coalesce((details->>'returnTouchdowns')::numeric,0) not between 0 and 1
         or (details->>'touchdowns')::numeric+coalesce((details->>'returnTouchdowns')::numeric,0)>1
         or (coalesce((details->>'returnTouchdowns')::numeric,0)=1 and (stats->>'points')::numeric<6)
       then raise exception 'Invalid offensive stats'; end if;
     else details:=null; end if;
     pts:=(stats->>'points')::integer;yds:=(stats->>'yards')::integer;snaps:=(stats->>'plays')::integer;
     if pts not in(0,3,6,7,8) or yds not between -200 and 500 or snaps not between 0 and 200 or (pts>=6 and snaps=0 and coalesce((details->>'returnTouchdowns')::integer,0)<>1) then raise exception 'Invalid drive stats'; end if;
   end if;
   update bk_football_private.drives set points=pts,yards=yds,plays=snaps,offense_stats=details,forfeited=p_action='forfeit',finished_at=now() where match_id=mid and user_id=me and ordinal=n;
   perform bk_football_private.settle(mid);
   return jsonb_build_object('saved',true,'points',pts,'forfeited',p_action='forfeit');
 end if;
 raise exception 'Unsupported football action';
end $function$

CREATE OR REPLACE FUNCTION bk_football_private.settle(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m bk_football_private.matches%rowtype; a integer; b integer;
begin
 select * into m from bk_football_private.matches where id=p_id for update;
 if m.status<>'active' then return; end if;
 update bk_football_private.drives set points=0,yards=0,plays=0,forfeited=true,finished_at=now()
 where match_id=p_id and finished_at is null and (deadline<=now() or m.expires_at<=now());
 if m.expires_at<=now() then
   insert into bk_football_private.drives(match_id,user_id,ordinal,launch_id,points,yards,plays,forfeited,finished_at)
   select p_id,u,n,gen_random_uuid(),0,0,0,true,now() from unnest(array[m.challenger_id,m.opponent_id]) u cross join generate_series(1,3) n
   on conflict do nothing;
 end if;
 if (select count(*) from bk_football_private.drives where match_id=p_id and finished_at is not null)=6 then
   select coalesce(sum(points) filter(where user_id=m.challenger_id),0),coalesce(sum(points) filter(where user_id=m.opponent_id),0) into a,b from bk_football_private.drives where match_id=p_id;
   update bk_football_private.matches set status='completed',completed_at=now(),winner_id=case when a>b then m.challenger_id when b>a then m.opponent_id else null end where id=p_id;
 end if;
end $function$

CREATE OR REPLACE FUNCTION bk_minigames_private.challenge_api(p_action text, p_args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=ball_knower_private.require_permanent_community_user();
 m bk_minigames_private.challenges%rowtype; a bk_minigames_private.attempts%rowtype;
 opponent uuid; challenge uuid; stats jsonb; scores numeric[]; key text; val jsonb; n numeric; maxval numeric; allowed text[]; round_index integer; fatigue numeric; total numeric; grade numeric; correct integer; expected_answer integer;
begin
 if p_args is null or jsonb_typeof(p_args)<>'object' or octet_length(p_args::text)>4096 then raise exception 'Invalid challenge request'; end if;
 if p_action='list' then
   update bk_minigames_private.challenges set status='expired' where status in('open','pending','active') and expires_at<=now() and (me in(challenger_id,opponent_id) or status='open');
   return coalesce((select jsonb_agg(row) from (
     select c.id,c.game,c.challenger_id,c.opponent_id,c.status,c.seed,c.expires_at,c.created_at,c.challenger_stats,c.opponent_stats,c.winner_id,
       coalesce(p.display_name,'Ball Knower') challenger_name,q.display_name opponent_name
     from bk_minigames_private.challenges c left join public.ball_knower_progress_profiles p on p.user_id=c.challenger_id left join public.ball_knower_progress_profiles q on q.user_id=c.opponent_id
     where (me in(c.challenger_id,c.opponent_id) or (c.status='open' and c.expires_at>now()))
       and not exists(select 1 from public.ball_knower_user_blocks b where (b.blocker_id=me and b.blocked_id in(c.challenger_id,c.opponent_id)) or (b.blocked_id=me and b.blocker_id in(c.challenger_id,c.opponent_id)))
       and not exists(select 1 from ball_knower_private.community_suspensions s where s.auth_user_id in(c.challenger_id,c.opponent_id) and s.expires_at>now())
     order by coalesce(me in(c.challenger_id,c.opponent_id),false) desc,c.created_at desc limit 100
   ) row),'[]'::jsonb);
 end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('bk-mini-user:'||me::text,0));
 if p_action='create' then
   if coalesce(p_args->>'game','') not in('dash','broad-jump','shuttle','bench','routes','one-on-one','rb','db','two-minute','five-minute','career') then raise exception 'Choose an available game'; end if;
   if (select count(*) from bk_minigames_private.challenges where challenger_id=me and created_at>now()-interval '1 hour')>=20 then raise exception 'Challenge limit reached. Try again later.'; end if;
   if (select count(*) from bk_minigames_private.challenges where challenger_id=me and status in('open','pending','active') and expires_at>now())>=5 then raise exception 'Finish or cancel an existing challenge first'; end if;
   opponent:=(p_args->>'opponent')::uuid;
   if opponent is not null then
     if opponent=me then raise exception 'Choose another Ball Knower'; end if;
     if not exists(select 1 from public.ball_knower_friendships where status='accepted' and (requester_id=me and recipient_id=opponent or requester_id=opponent and recipient_id=me)) then raise exception 'Choose an accepted friend'; end if;
     if not bk_minigames_private.available(opponent) then raise exception 'Opponent is unavailable'; end if;
     if exists(select 1 from public.ball_knower_user_blocks where (blocker_id=me and blocked_id=opponent) or (blocker_id=opponent and blocked_id=me)) then raise exception 'Opponent is unavailable'; end if;
   end if;
   insert into bk_minigames_private.challenges(game,challenger_id,opponent_id,status) values(p_args->>'game',me,opponent,case when opponent is null then 'open' else 'pending' end) returning id into challenge;
   return jsonb_build_object('id',challenge);
 end if;
 challenge:=(p_args->>'id')::uuid;
 select * into m from bk_minigames_private.challenges where id=challenge for update;
 if not found then raise exception 'Challenge is unavailable'; end if;
 if exists(select 1 from public.ball_knower_user_blocks b where (b.blocker_id=me and b.blocked_id in(m.challenger_id,m.opponent_id)) or (b.blocked_id=me and b.blocker_id in(m.challenger_id,m.opponent_id))) then raise exception 'Challenge is unavailable'; end if;
 if m.expires_at<=now() and m.status in('open','pending','active') then raise exception 'This challenge has expired. Start a new one.'; end if;
 if p_action='accept' then
   if m.challenger_id=me or m.status not in('open','pending') or (m.status='pending' and m.opponent_id<>me) then raise exception 'Challenge cannot be accepted'; end if;
   if not bk_minigames_private.available(m.challenger_id) then raise exception 'Opponent is unavailable'; end if;
   if (select count(*) from bk_minigames_private.challenges where opponent_id=me and status='active' and expires_at>now())>=10 then raise exception 'Finish your active challenges first'; end if;
   update bk_minigames_private.challenges set opponent_id=me,status='active' where id=challenge;
   return jsonb_build_object('id',challenge);
 end if;
 if me<>m.challenger_id and me is distinct from m.opponent_id then raise exception 'Challenge is unavailable'; end if;
 if p_action='cancel' and me=m.challenger_id and m.status in('open','pending') then
   update bk_minigames_private.challenges set status='cancelled' where id=challenge;return '{}'::jsonb;
 elsif p_action='decline' and me=m.opponent_id and m.status='pending' then
   update bk_minigames_private.challenges set status='declined' where id=challenge;return '{}'::jsonb;
 end if;
 if p_action='submit' and ((me=m.challenger_id and m.challenger_stats is not null) or (me=m.opponent_id and m.opponent_stats is not null)) then
   -- Retry after a lost response is safe, but never changes a locked result.
   return jsonb_build_object('status',m.status,'winner_id',m.winner_id,'stats',case when me=m.challenger_id then m.challenger_stats else m.opponent_stats end);
 end if;
 if m.status<>'active' then raise exception 'This challenge is not active'; end if;
 if not bk_minigames_private.available(case when me=m.challenger_id then m.opponent_id else m.challenger_id end) then raise exception 'Opponent is unavailable'; end if;
 if p_action='begin' then
   if (me=m.challenger_id and m.challenger_stats is not null) or (me=m.opponent_id and m.opponent_stats is not null) then raise exception 'Your result is already locked'; end if;
   insert into bk_minigames_private.attempts(challenge_id,user_id) values(challenge,me) on conflict do nothing;
   select * into a from bk_minigames_private.attempts where challenge_id=challenge and user_id=me;
   return jsonb_build_object('token',a.token);
 elsif p_action='submit' then
   select * into a from bk_minigames_private.attempts where challenge_id=challenge and user_id=me;
   if not found or a.token is distinct from (p_args->>'token')::uuid then raise exception 'Start your challenge turn before posting a result'; end if;
   if a.started_at>now()-interval '2 seconds' then raise exception 'Finish the game before posting a result'; end if;
   stats:=p_args->'stats';
   if stats is null or jsonb_typeof(stats)<>'object' then raise exception 'Invalid game stats'; end if;
   allowed:=case when m.game='career' then array['raw0','raw1','raw2','prep0','prep1','prep2','film0','film1','film2'] when m.game='dash' then array['time','split10','split20','dnf'] when m.game='shuttle' then array['time','penalty'] when m.game='bench' then array['reps'] when m.game='broad-jump' then array['distance'] when m.game in('two-minute','five-minute') then array['points','yards','passYards','rushYards','turnovers','touchdowns','plays'] else array['score','reps','catches','stops','picks','yards','touchdowns'] end;
   for key,val in select * from jsonb_each(stats) loop
     if not key=any(allowed) or jsonb_typeof(val)<>'number' then raise exception 'Invalid game stat'; end if;
     n:=val::text::numeric;
     maxval:=case when key like 'raw%' then 100 when key like 'prep%' or key like 'film%' then 2 when key in('time','penalty') then 120 when key='distance' then 5 when key in('score','points') then 100 when key='dnf' then 1 when key in('yards','passYards','rushYards') then 2000 else 200 end;
     if n<(case when key in('yards','passYards','rushYards') then -200 else 0 end) or n>maxval then raise exception 'Game stat is outside the supported range'; end if;
     if key not in('time','penalty','distance','split10','split20') and n<>trunc(n) then raise exception 'Game count must be a whole number'; end if;
   end loop;
   if m.game='career' then
     if not stats ?& array['raw0','raw1','raw2','prep0','prep1','prep2','film0','film1','film2'] then raise exception 'Complete all three career weeks before submitting'; end if;
     fatigue:=20;total:=0;correct:=0;
     for round_index in 0..2 loop
       fatigue:=greatest(0,least(100,fatigue+case (stats->>('prep'||round_index))::int when 0 then 18 when 1 then 5 else -24 end));
       expected_answer:=case mod(m.seed+round_index,3) when 0 then 1 when 1 then 0 else 2 end;
       grade:=(stats->>('raw'||round_index))::numeric+case (stats->>('prep'||round_index))::int when 0 then 6 when 1 then 3 else -2 end;
       if (stats->>('film'||round_index))::int=expected_answer then grade:=grade+3;correct:=correct+1;end if;
       total:=total+round(greatest(0,least(100,grade-greatest(0,fatigue-35)*0.12)));
       fatigue:=greatest(0,fatigue-12);
     end loop;
     scores:=array[round(total/3)];
     stats:=stats||jsonb_build_object('score',scores[1],'rounds',3,'correct',correct,'validated',1);
   elsif m.game in('dash','shuttle') then
     if not stats?'time' or (stats->>'time')::numeric<1 then raise exception 'A completed time is required'; end if;
     if m.game='dash' and coalesce((stats->>'dnf')::int,0)=0 and (not stats?'split10' or not stats?'split20' or (stats->>'split10')::numeric<=0 or (stats->>'split10')::numeric>=(stats->>'split20')::numeric or (stats->>'split20')::numeric>=(stats->>'time')::numeric) then raise exception 'Invalid split times'; end if;
     scores:=array[case when coalesce((stats->>'dnf')::int,0)=1 then -120000 else -round((stats->>'time')::numeric*1000) end];
   elsif m.game='broad-jump' then
     if not stats?'distance' then raise exception 'Jump distance is required'; end if;scores:=array[round((stats->>'distance')::numeric*1000)];
   elsif m.game='bench' then
     if not stats?'reps' then raise exception 'Rep count is required'; end if;scores:=array[(stats->>'reps')::numeric];
   elsif m.game in('two-minute','five-minute') then
     if not stats ?& array['points','yards','turnovers'] then raise exception 'Complete game stats are required'; end if;
     scores:=array[(stats->>'points')::numeric,(stats->>'yards')::numeric,-(stats->>'turnovers')::numeric];
   else
     if not stats ?& array['score','reps'] or (stats->>'reps')::int<>(case when m.game='routes' then 8 else 5 end) then raise exception 'Complete every rep before posting a score'; end if;
     scores:=array[(stats->>'score')::numeric];
   end if;
   if me=m.challenger_id then update bk_minigames_private.challenges set challenger_stats=stats,challenger_score=scores where id=challenge;
   else update bk_minigames_private.challenges set opponent_stats=stats,opponent_score=scores where id=challenge;end if;
   select * into m from bk_minigames_private.challenges where id=challenge;
   if m.challenger_stats is not null and m.opponent_stats is not null then
     update bk_minigames_private.challenges set status='completed',winner_id=case when challenger_score>opponent_score then challenger_id when opponent_score>challenger_score then opponent_id else null end where id=challenge;
   end if;
   return jsonb_build_object('saved',true,'stats',stats);
 end if;
 raise exception 'Unsupported challenge action';
end $function$

CREATE OR REPLACE FUNCTION public.apply_ball_knower_player_move(p_league_id text, p_member_id text, p_player_snapshot jsonb, p_drop_player_id text, p_faab_bid numeric, p_kind text, p_claim_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_member public.ball_knower_league_members%rowtype;v_settings jsonb;v_roster jsonb;v_new_roster jsonb;v_drop jsonb;v_player_id text;v_player_name text;v_limit integer;v_days integer;v_ir jsonb;v_active integer;v_week integer;v_season integer;v_week_limit integer;v_season_limit integer;v_week_count integer;v_season_count integer;v_reset_at timestamptz;
begin
  perform set_config('ball_knower.authorized_roster_operation','waiver',true);
  v_player_id:=p_player_snapshot->>'id';v_player_name:=coalesce(p_player_snapshot->>'name',v_player_id);
  if v_player_id is null or v_player_id='' then raise exception 'Player data is missing';end if;
  select l.settings into v_settings from public.ball_knower_leagues l where l.id=p_league_id for update;
  if not found then raise exception 'League not found';end if;
  perform 1 from public.ball_knower_league_members where league_id=p_league_id order by id for update;
  if exists(select 1 from public.ball_knower_league_members m,jsonb_array_elements(coalesce(m.roster,'[]'::jsonb))e where m.league_id=p_league_id and e->>'id'=v_player_id) then raise exception 'Player is no longer available';end if;
  select * into v_member from public.ball_knower_league_members where league_id=p_league_id and id=p_member_id;
  if not found then raise exception 'League member not found';end if;
  if p_faab_bid<0 or p_faab_bid>v_member.faab_balance then raise exception 'FAAB bid exceeds remaining budget';end if;
  v_roster:=coalesce(v_member.roster,'[]'::jsonb);v_limit:=public.ball_knower_fantasy_roster_size(p_league_id);
  select coalesce(jsonb_agg(id.value),'[]'::jsonb) into v_ir from jsonb_array_elements_text(coalesce(v_member.ir_player_ids,'[]'::jsonb))id(value) where exists(select 1 from jsonb_array_elements(v_roster)p where p->>'id'=id.value);
  if p_drop_player_id is not null then
    select e into v_drop from jsonb_array_elements(v_roster)e where e->>'id'=p_drop_player_id limit 1;
    if v_drop is null then raise exception 'Drop player is no longer on this roster';end if;
    if public.ball_knower_started_starter(p_league_id,v_member.id,p_drop_player_id) then raise exception 'A started player locked in this week''s lineup cannot be dropped';end if;
  else
    v_active:=jsonb_array_length(v_roster)-jsonb_array_length(v_ir);
    if v_active>=v_limit then raise exception 'Choose a player to drop from the full active roster';end if;
  end if;
  v_week:=coalesce(nullif(v_settings->>'currentWeek','')::integer,1);v_season:=coalesce(nullif(v_settings->>'nflSeason','')::integer,extract(year from now())::integer);
  v_week_limit:=coalesce(nullif(v_settings->>'maxAcquisitionsPerWeek','')::integer,0);v_season_limit:=coalesce(nullif(v_settings->>'maxAcquisitionsPerSeason','')::integer,0);
  v_reset_at:=coalesce(nullif(v_settings->>'fantasySeasonResetAt','')::timestamptz,'-infinity'::timestamptz);
  select count(*) filter(where coalesce((metadata->>'acquisitionWeek')::integer,-1)=v_week),count(*) into v_week_count,v_season_count from public.ball_knower_transactions where league_id=p_league_id and member_id=v_member.id and transaction_type in('free_agent','waiver') and coalesce((metadata->>'acquisitionSeason')::integer,-1)=v_season and created_at>=v_reset_at;
  if v_week_limit>0 and v_week_count>=v_week_limit then raise exception 'Weekly acquisition limit reached';end if;
  if v_season_limit>0 and v_season_count>=v_season_limit then raise exception 'Season acquisition limit reached';end if;
  select coalesce(jsonb_agg(e),'[]'::jsonb) into v_new_roster from jsonb_array_elements(v_roster)e where p_drop_player_id is null or e->>'id'<>p_drop_player_id;
  v_new_roster:=v_new_roster||jsonb_build_array(p_player_snapshot);
  select coalesce(jsonb_agg(id.value),'[]'::jsonb) into v_ir from jsonb_array_elements_text(v_ir)id(value) where id.value<>coalesce(p_drop_player_id,'');
  v_active:=jsonb_array_length(v_new_roster)-jsonb_array_length(v_ir);
  if v_active>v_limit then raise exception 'Move would exceed the active roster limit';end if;
  update public.ball_knower_league_members set roster=v_new_roster,ir_player_ids=v_ir,status='building',team_ratings=null,submitted_at=null,faab_balance=greatest(0,faab_balance-p_faab_bid) where id=v_member.id;
  delete from public.ball_knower_player_waivers where league_id=p_league_id and player_id=v_player_id;
  if v_drop is not null then
    v_days:=greatest(0,least(7,coalesce(nullif(v_settings->>'waiverDays','')::integer,2)));
    insert into public.ball_knower_player_waivers(league_id,player_id,player_snapshot,dropped_by_member_id,clears_at) values(p_league_id,p_drop_player_id,v_drop,v_member.id,now()+make_interval(days=>v_days)) on conflict(league_id,player_id) do update set player_snapshot=excluded.player_snapshot,dropped_by_member_id=excluded.dropped_by_member_id,clears_at=excluded.clears_at,created_at=now();
  end if;
  insert into public.ball_knower_transactions(league_id,member_id,transaction_type,summary,metadata) values(p_league_id,v_member.id,p_kind,v_member.user_name||' added '||v_player_name||case when v_drop is null then '.' else ' and dropped '||coalesce(v_drop->>'name',p_drop_player_id)||'.' end,jsonb_build_object('claimId',p_claim_id,'playerId',v_player_id,'dropPlayerId',p_drop_player_id,'faabBid',p_faab_bid,'kind',p_kind,'acquisitionWeek',v_week,'acquisitionSeason',v_season));
  return jsonb_build_object('playerId',v_player_id,'dropPlayerId',p_drop_player_id,'memberId',v_member.id);
end;$function$

CREATE OR REPLACE FUNCTION public.ball_knower_enforce_event_actor()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_requester uuid := public.fantasy_requester_id();
  v_actor_name text;
begin
  if v_requester is null then
    raise exception 'Authentication required';
  end if;

  if not public.can_access_ball_knower_league(new.league_id) then
    raise exception 'League access required';
  end if;

  select m.user_name
    into v_actor_name
  from public.ball_knower_league_members m
  where m.league_id = new.league_id
    and m.auth_user_id = v_requester
  limit 1;

  if v_actor_name is null then
    select l.commissioner_name
      into v_actor_name
    from public.ball_knower_leagues l
    where l.id = new.league_id
      and l.commissioner_auth_id = v_requester
    limit 1;
  end if;

  new.actor_auth_id := v_requester;
  new.actor_name := coalesce(nullif(trim(v_actor_name), ''), 'Ball Knower');
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ball_knower_enforce_notification_target()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_requester uuid:=public.fantasy_requester_id();
  v_authorized_operation text:=current_setting('ball_knower.authorized_notification_operation',true);
begin
  if coalesce(v_authorized_operation,'')='system' then
    if new.league_id is null or not exists(
      select 1 from public.ball_knower_league_members m
      where m.league_id=new.league_id and m.auth_user_id=new.auth_user_id and not coalesce(m.is_ai,false)
    ) then raise exception 'System notification recipient is not a human league member'; end if;
    return new;
  end if;
  if v_requester is null then raise exception 'Authentication required'; end if;
  if new.league_id is null then
    if new.auth_user_id<>v_requester then raise exception 'Cannot create a notification for another user'; end if;
    return new;
  end if;
  if new.auth_user_id=v_requester then
    if not public.can_access_ball_knower_league(new.league_id) then raise exception 'League access required'; end if;
    return new;
  end if;
  if not public.is_ball_knower_commissioner(new.league_id) then raise exception 'Commissioner access required for league notification fanout'; end if;
  if not exists(
    select 1 from public.ball_knower_league_members m
    where m.league_id=new.league_id and m.auth_user_id=new.auth_user_id and not coalesce(m.is_ai,false)
  ) then raise exception 'Notification recipient is not a human member of this league'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ball_knower_league_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_max_members integer;
  v_member_count integer;
begin
  select l.max_members
  into v_max_members
  from public.ball_knower_leagues l
  where l.id = new.league_id
  for update;

  if v_max_members is null then
    raise exception 'League not found';
  end if;

  select count(*)
  into v_member_count
  from public.ball_knower_league_members m
  where m.league_id = new.league_id;

  if v_member_count >= v_max_members then
    raise exception 'League is full';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_ball_knower_member_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_requester uuid:=public.fantasy_requester_id();v_is_commissioner boolean:=public.is_ball_knower_commissioner(new.league_id);v_paused boolean;v_rosters_locked boolean;v_roster_count integer;v_authorized_operation text:=current_setting('ball_knower.authorized_roster_operation',true);
begin
  if v_requester is null and coalesce(v_authorized_operation,'') not in ('trade','waiver','system') then raise exception 'Authentication required'; end if;
  if not v_is_commissioner and old.auth_user_id=v_requester then
    if new.id is distinct from old.id or new.league_id is distinct from old.league_id or new.auth_user_id is distinct from old.auth_user_id or new.app_user_id is distinct from old.app_user_id or new.is_commissioner is distinct from old.is_commissioner or new.is_ai is distinct from old.is_ai then raise exception 'League membership identity fields cannot be changed by members'; end if;
  end if;
  select league.paused,league.rosters_locked into v_paused,v_rosters_locked from public.ball_knower_leagues league where league.id=new.league_id;
  if not found then raise exception 'League not found'; end if;
  if not v_is_commissioner and old.auth_user_id=v_requester and coalesce(v_authorized_operation,'') not in ('trade','waiver') and (new.roster is distinct from old.roster or new.team_ratings is distinct from old.team_ratings or new.status is distinct from old.status or new.submitted_at is distinct from old.submitted_at) then
    if v_paused then raise exception 'This league is paused by the commissioner'; end if;
    if v_rosters_locked then raise exception 'Roster submissions are currently locked by the commissioner'; end if;
  end if;
  if new.status='ready' and (new.status is distinct from old.status or new.roster is distinct from old.roster) then
    v_roster_count:=jsonb_array_length(coalesce(new.roster,'[]'::jsonb));
    if coalesce(v_authorized_operation,'') in ('trade','waiver') then
      if v_roster_count>public.ball_knower_fantasy_roster_size(new.league_id) then raise exception 'Roster cannot exceed % players',public.ball_knower_fantasy_roster_size(new.league_id); end if;
    elsif v_roster_count<>public.ball_knower_fantasy_roster_size(new.league_id) then raise exception 'A ready roster must contain exactly % players',public.ball_knower_fantasy_roster_size(new.league_id); end if;
  end if;
  return new;
end;$function$

CREATE OR REPLACE FUNCTION public.enforce_ball_knower_roster_submission_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_paused boolean;
  v_rosters_locked boolean;
  v_authorized_operation text := current_setting('ball_knower.authorized_roster_operation', true);
begin
  if coalesce(v_authorized_operation,'') in ('trade','waiver') then return new; end if;
  if (select auth.uid()) is distinct from old.auth_user_id then return new; end if;
  if new.roster is not distinct from old.roster and new.team_ratings is not distinct from old.team_ratings and new.submitted_at is not distinct from old.submitted_at and new.status is not distinct from old.status then return new; end if;
  select paused, rosters_locked into v_paused, v_rosters_locked from public.ball_knower_leagues where id = old.league_id;
  if coalesce(v_paused, false) then raise exception 'This league is paused by the commissioner.'; end if;
  if coalesce(v_rosters_locked, false) then raise exception 'Roster submissions are currently locked by the commissioner.'; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_ball_knower_live_draft_rosters(p_league_id text, p_assignments jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth uuid:=(select auth.uid());
  v_already_finalized boolean:=false;
begin
  if v_auth is null then
    select exists(
      select 1
      from public.ball_knower_live_drafts draft
      join public.ball_knower_leagues league on league.id=draft.league_id
      where draft.league_id=p_league_id
        and draft.status='completed'
        and league.rosters_locked
        and not exists(
          select 1
          from public.ball_knower_league_members member
          where member.league_id=p_league_id
            and (member.status<>'ready' or coalesce(jsonb_array_length(member.roster),0)<>draft.rounds)
        )
    ) into v_already_finalized;
    if v_already_finalized then return true; end if;
    raise exception 'Authentication required';
  end if;

  if not exists(
    select 1
    from public.ball_knower_league_members requester
    where requester.league_id=p_league_id
      and requester.auth_user_id=v_auth
      and coalesce(requester.is_ai,false)=false
  ) then
    raise exception 'Only league members can finalize completed fantasy rosters';
  end if;

  return ball_knower_private.finalize_completed_live_draft(p_league_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.join_ball_knower_league(p_code text, p_user_name text, p_user_avatar text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth uuid := (select auth.uid());
  v_league public.ball_knower_leagues%rowtype;
  v_existing text;
  v_member_count integer;
  v_name text := left(coalesce(nullif(btrim(p_user_name), ''), 'Ball Knower'), 60);
begin
  if v_auth is null then raise exception 'Authentication required'; end if;

  select *
  into v_league
  from public.ball_knower_leagues
  where upper(code) = upper(btrim(p_code))
  for update;

  if not found then raise exception 'League not found'; end if;
  if v_league.invite_enabled is false then raise exception 'League invite disabled'; end if;
  if v_league.paused is true then raise exception 'League is paused'; end if;
  if v_league.status <> 'drafting' then raise exception 'League is no longer accepting members'; end if;

  select id
  into v_existing
  from public.ball_knower_league_members
  where league_id = v_league.id and auth_user_id = v_auth
  limit 1;

  if v_existing is not null then return v_league.id; end if;

  select count(*)
  into v_member_count
  from public.ball_knower_league_members
  where league_id = v_league.id;

  if v_member_count >= v_league.max_members then raise exception 'League is full'; end if;

  insert into public.ball_knower_league_members(
    id, league_id, auth_user_id, app_user_id, user_name, user_avatar,
    is_commissioner, is_ai, status
  ) values (
    'member-' || v_auth::text || '-' || floor(extract(epoch from clock_timestamp()) * 1000)::bigint::text,
    v_league.id, v_auth, v_auth::text, v_name, left(p_user_avatar, 1000), false, false, 'building'
  )
  on conflict (league_id, auth_user_id) where auth_user_id is not null do nothing;

  return v_league.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.log_ball_knower_league_event(p_league_id text, p_event_type text, p_message text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_requester uuid := public.fantasy_requester_id();
  v_actor_name text;
  v_id uuid;
begin
  if v_requester is null then
    raise exception 'Authentication required';
  end if;
  if not public.can_access_ball_knower_league(p_league_id) then
    raise exception 'League access required';
  end if;
  if nullif(trim(p_event_type), '') is null or length(p_event_type) > 64 then
    raise exception 'Invalid event type';
  end if;
  if nullif(trim(p_message), '') is null or length(p_message) > 1000 then
    raise exception 'Invalid event message';
  end if;

  select m.user_name into v_actor_name
  from public.ball_knower_league_members m
  where m.league_id = p_league_id and m.auth_user_id = v_requester
  limit 1;

  if v_actor_name is null then
    select l.commissioner_name into v_actor_name
    from public.ball_knower_leagues l
    where l.id = p_league_id and l.commissioner_auth_id = v_requester
    limit 1;
  end if;

  insert into public.ball_knower_league_events(
    league_id, actor_auth_id, actor_name, event_type, message, metadata
  ) values (
    p_league_id, v_requester,
    coalesce(nullif(trim(v_actor_name), ''), 'Ball Knower'),
    trim(p_event_type), trim(p_message), coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.make_ball_knower_live_draft_pick(p_league_id text, p_player_id text, p_group text, p_final_assignments jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth uuid:=(select auth.uid());v_draft public.ball_knower_live_drafts%rowtype;v_member public.ball_knower_league_members%rowtype;
  v_team_count integer;v_total_picks integer;v_round_index integer;v_slot integer;v_order_index integer;v_member_id text;
  v_selected_player_id text;v_canonical_group text;v_group_count integer;v_group_limit integer;v_pick jsonb;v_next_index integer;
  v_member_pick_count integer;v_picks_remaining integer;v_missing_count integer;v_required_now boolean;
begin
  if v_auth is null then raise exception 'Authentication required'; end if;
  select * into v_draft from public.ball_knower_live_drafts where league_id=p_league_id for update;
  if not found then raise exception 'Fantasy draft has not started'; end if;if v_draft.status<>'active' then raise exception 'Fantasy draft is already complete'; end if;
  v_team_count:=jsonb_array_length(v_draft.order_member_ids);v_total_picks:=v_team_count*v_draft.rounds;
  if v_team_count<1 or v_draft.pick_index>=v_total_picks then raise exception 'Fantasy draft is already complete'; end if;
  v_round_index:=v_draft.pick_index/v_team_count;v_slot:=mod(v_draft.pick_index,v_team_count);v_order_index:=case when mod(v_round_index,2)=0 then v_slot else v_team_count-1-v_slot end;v_member_id:=v_draft.order_member_ids->>v_order_index;
  select * into v_member from public.ball_knower_league_members where league_id=p_league_id and id=v_member_id;if not found then raise exception 'The manager on the clock is no longer in the league'; end if;

  if coalesce(v_member.is_ai,false) then
    if not exists(select 1 from public.ball_knower_league_members requester where requester.league_id=p_league_id and requester.auth_user_id=v_auth and coalesce(requester.is_ai,false)=false) then raise exception 'Only league members can advance CPU picks';end if;
    select count(*) into v_member_pick_count from jsonb_array_elements(v_draft.picks) prior where prior->>'memberId'=v_member_id;
    v_picks_remaining:=v_draft.rounds-v_member_pick_count;
    select sum(greatest(requirement.minimum-coalesce(picked.position_count,0),0))::integer into v_missing_count
    from (values ('QB',1),('RB',2),('WR',2),('TE',1),('K',1),('DST',1)) requirement(draft_group,minimum)
    left join lateral(select count(*)::integer position_count from jsonb_array_elements(v_draft.picks) prior where prior->>'memberId'=v_member_id and prior->>'group'=requirement.draft_group)picked on true;
    v_required_now:=v_picks_remaining<=coalesce(v_missing_count,0);

    select candidate.player_id,candidate.draft_group into v_selected_player_id,v_canonical_group
    from (
      select g.player_id,g.draft_group,coalesce(picked.position_count,0) position_count,ranked.overall_rank,
        coalesce(case when (p.player_json->>'ovr')~'^[0-9]+([.][0-9]+)?$' then (p.player_json->>'ovr')::numeric end,0) ovr,
        case g.draft_group when 'QB' then 2 when 'RB' then 5 when 'WR' then 7 when 'TE' then 2 when 'K' then 2 when 'DST' then 2 end position_limit,
        case g.draft_group when 'QB' then 75 when 'TE' then 62 when 'K' then 45 when 'DST' then 45 when 'RB' then 14 else 10 end depth_penalty,
        case g.draft_group when 'QB' then 1 when 'RB' then 2 when 'WR' then 2 when 'TE' then 1 when 'K' then 1 when 'DST' then 1 end starter_minimum
      from public.ball_knower_fantasy_player_groups g
      left join ball_knower_private.draft_order_game_players p on p.player_id=g.player_id
      left join lateral(select count(*)::integer position_count from jsonb_array_elements(v_draft.picks) prior where prior->>'memberId'=v_member_id and prior->>'group'=g.draft_group)picked on true
      left join lateral(select min(r.overall_rank) overall_rank from public.ball_knower_fantasy_rankings r where r.season=2026 and r.scoring_format='ppr' and lower(regexp_replace(r.player_name,'[^a-z0-9]','','g'))=lower(regexp_replace(coalesce(p.player_json->>'name',''),'[^a-z0-9]','','g')))ranked on true
      where g.draft_group in ('QB','RB','WR','TE','K','DST') and (p.player_id is not null or g.draft_group='DST')
        and not exists(select 1 from jsonb_array_elements(v_draft.picks) prior where prior->>'playerId'=g.player_id)
    ) candidate
    where candidate.position_count<candidate.position_limit and (not v_required_now or candidate.position_count<candidate.starter_minimum)
    order by case when candidate.position_count<candidate.starter_minimum then 0 else 1 end,
      coalesce(candidate.overall_rank,9999)+candidate.position_count*candidate.depth_penalty+
        case when candidate.draft_group in ('K','DST') and v_member_pick_count<13 then 500 else 0 end,
      candidate.ovr desc,candidate.player_id limit 1;
    if v_selected_player_id is null then raise exception 'No legal CPU fantasy player remains'; end if;
  else
    if coalesce((select settings->>'draftFormat' from public.ball_knower_leagues where id=p_league_id),'live_snake')='autopick' then raise exception 'This league uses an autopick-only draft';end if;
    if v_member.auth_user_id<>v_auth then raise exception '% is on the clock',v_member.user_name;end if;
    if nullif(btrim(p_player_id),'') is null then raise exception 'Player id is required';end if;
    v_selected_player_id:=p_player_id;select draft_group into v_canonical_group from public.ball_knower_fantasy_player_groups where player_id=v_selected_player_id;
    if not found then raise exception 'That player is not in the current fantasy player index';end if;if v_canonical_group<>p_group then raise exception 'Player position does not match the submitted draft group';end if;
  end if;
  if v_canonical_group not in ('QB','RB','WR','TE','K','DST') then raise exception 'Only QB, RB, WR, TE, K and D/ST are valid fantasy positions';end if;
  if exists(select 1 from jsonb_array_elements(v_draft.picks) prior where prior->>'playerId'=v_selected_player_id) then raise exception 'That player was already drafted';end if;
  select count(*) into v_group_count from jsonb_array_elements(v_draft.picks) prior where prior->>'memberId'=v_member_id and prior->>'group'=v_canonical_group;
  if coalesce(v_member.is_ai,false) then
    v_group_limit:=case v_canonical_group when 'QB' then 2 when 'RB' then 5 when 'WR' then 7 when 'TE' then 2 when 'K' then 2 when 'DST' then 2 end;
    if v_group_count>=v_group_limit then raise exception '% reached the % CPU roster limit',v_member.user_name,v_canonical_group;end if;
  end if;
  v_pick:=jsonb_build_object('overall',v_draft.pick_index+1,'round',v_round_index+1,'memberId',v_member_id,'playerId',v_selected_player_id,'group',v_canonical_group,'pickedAt',clock_timestamp());v_next_index:=v_draft.pick_index+1;
  update public.ball_knower_live_drafts set picks=picks||jsonb_build_array(v_pick),pick_index=v_next_index,status=case when v_next_index>=v_total_picks then 'completed' else 'active' end,completed_at=case when v_next_index>=v_total_picks then clock_timestamp() else null end,updated_at=clock_timestamp() where league_id=p_league_id returning * into v_draft;
  if v_next_index>=v_total_picks then perform public.finalize_ball_knower_live_draft_rosters(p_league_id,null);end if;return to_jsonb(v_draft);
end;$function$

CREATE OR REPLACE FUNCTION public.next_ball_knower_waiver_run(p_settings jsonb, p_from timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_hour integer:=greatest(0,least(23,coalesce(nullif(p_settings->>'waiverProcessHourUtc','')::integer,9)));v_days jsonb:=coalesce(p_settings->'waiverRunDays','[0,1,2,3,4,5,6]'::jsonb);v_candidate timestamptz;v_offset integer;
begin
  for v_offset in 0..7 loop
    v_candidate:=date_trunc('day',p_from)+(v_offset||' days')::interval+(v_hour||' hours')::interval;
    if v_candidate>p_from and exists(select 1 from jsonb_array_elements_text(v_days) d(value) where d.value=extract(dow from v_candidate)::integer::text) then return v_candidate; end if;
  end loop;
  return date_trunc('day',p_from)+interval '1 day'+(v_hour||' hours')::interval;
end;$function$

CREATE OR REPLACE FUNCTION public.normalize_ball_knower_player_waiver_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_settings jsonb;
begin
  select settings into v_settings from public.ball_knower_leagues where id=new.league_id;
  if not found then raise exception 'League not found'; end if;
  -- Drops begin with a duration-based timestamp. Snap it forward to the first
  -- configured processing run so claims remain protected until the real run.
  new.clears_at:=public.next_ball_knower_waiver_run(v_settings,new.clears_at-interval '1 second');
  return new;
end;$function$

CREATE OR REPLACE FUNCTION public.preserve_ball_knower_pregame_projection()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.pregame_projection_captured_at is not null then
    new.opponent_team := old.opponent_team;
    new.is_home := old.is_home;
    new.pregame_projected_points := old.pregame_projected_points;
    new.pregame_projection_reason := old.pregame_projection_reason;
    new.pregame_projection_source := old.pregame_projection_source;
    new.pregame_projection_captured_at := old.pregame_projection_captured_at;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_ball_knower_friend_request(p_friendship_id uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=ball_knower_private.require_permanent_community_user();
begin
  if p_accept then update public.ball_knower_friendships set status='accepted',updated_at=now() where id=p_friendship_id and recipient_id=me and status='pending';
  else delete from public.ball_knower_friendships where id=p_friendship_id and me in(requester_id,recipient_id); end if;
  if not found then raise exception 'Friend request is unavailable'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.save_my_ball_knower_notification_preference(p_category text, p_in_app_enabled boolean, p_push_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth uuid := (select auth.uid());
begin
  if v_auth is null then raise exception 'Authentication required'; end if;
  if p_category is null or p_category not in ('draft','roster','transactions','league') then
    raise exception 'Invalid notification category';
  end if;
  if p_in_app_enabled is null or p_push_enabled is null then
    raise exception 'Notification preferences must be explicit';
  end if;

  insert into public.ball_knower_notification_preferences(
    auth_user_id, category, in_app_enabled, push_enabled, updated_at
  ) values (
    v_auth, p_category, p_in_app_enabled, p_push_enabled, now()
  )
  on conflict (auth_user_id, category) do update
  set in_app_enabled = excluded.in_app_enabled,
      push_enabled = excluded.push_enabled,
      updated_at = excluded.updated_at;
end
$function$

CREATE OR REPLACE FUNCTION public.save_my_ball_knower_weekly_lineup(p_league_id text, p_week_number integer, p_starters jsonb, p_bench jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth uuid := auth.uid();
  v_member public.ball_knower_league_members%rowtype;
  v_existing public.ball_knower_weekly_lineups%rowtype;
  v_roster jsonb;
  v_player jsonb;
  v_player_id text;
  v_old_player_id text;
  v_slot text;
  v_position text;
  v_team text;
  v_seen text[] := '{}';
  v_locked jsonb := '[]'::jsonb;
  v_is_started boolean;
  v_has_existing boolean := false;
  v_required_slots text[] := array['QB','RB1','RB2','WR1','WR2','TE','FLEX','K','DST'];
  v_id uuid;
  v_season integer;
begin
  if v_auth is null then raise exception 'Authentication required'; end if;
  if p_week_number < 1 or p_week_number > 22 then raise exception 'Invalid week'; end if;
  if jsonb_typeof(p_starters) <> 'object' then raise exception 'Starters must be an object'; end if;
  if jsonb_typeof(coalesce(p_bench,'[]'::jsonb)) <> 'array' then raise exception 'Bench must be an array'; end if;

  select * into v_member
  from public.ball_knower_league_members
  where league_id = p_league_id and auth_user_id = v_auth
  limit 1;
  if not found then raise exception 'League membership not found'; end if;
  v_roster := coalesce(v_member.roster,'[]'::jsonb);

  select coalesce(nullif(settings->>'nflSeason','')::integer, extract(year from now())::integer)
  into v_season
  from public.ball_knower_leagues
  where id = p_league_id;

  select * into v_existing
  from public.ball_knower_weekly_lineups
  where league_id = p_league_id and member_id = v_member.id and week_number = p_week_number
  for update;
  v_has_existing := found;

  foreach v_slot in array v_required_slots loop
    v_player_id := p_starters->>v_slot;
    if v_player_id is null or v_player_id = '' then raise exception '% is empty', v_slot; end if;
    if v_player_id = any(v_seen) then raise exception 'A player cannot fill more than one lineup slot'; end if;
    v_seen := array_append(v_seen,v_player_id);

    select e into v_player from jsonb_array_elements(v_roster) e where e->>'id' = v_player_id limit 1;
    if v_player is null then raise exception '% starter is not on your roster', v_slot; end if;
    v_position := v_player->>'position';
    if (v_slot='QB' and v_position<>'QB')
      or (v_slot in('RB1','RB2') and v_position not in('RB','FB'))
      or (v_slot in('WR1','WR2') and v_position<>'WR')
      or (v_slot='TE' and v_position<>'TE')
      or (v_slot='FLEX' and v_position not in('RB','FB','WR','TE'))
      or (v_slot='K' and v_position<>'K')
      or (v_slot='DST' and v_position<>'DST')
    then raise exception '% is not eligible for %', coalesce(v_player->>'name',v_player_id), v_slot; end if;
  end loop;

  if v_has_existing then
    for v_slot, v_old_player_id in select key, value from jsonb_each_text(v_existing.starters) loop
      select e->>'team' into v_team from jsonb_array_elements(v_roster) e where e->>'id'=v_old_player_id limit 1;
      select exists(
        select 1 from public.ball_knower_nfl_games g
        where g.season=v_season and g.week_number=p_week_number
          and (g.home_team=v_team or g.away_team=v_team) and g.kickoff_at<=now()
      ) into v_is_started;
      if v_is_started or exists(select 1 from jsonb_array_elements_text(coalesce(v_existing.locked_player_ids,'[]'::jsonb)) x where x=v_old_player_id) then
        v_locked := v_locked || to_jsonb(v_old_player_id);
        if p_starters->>v_slot is distinct from v_old_player_id then
          raise exception '% is locked in the % slot because his game has started', coalesce((select e->>'name' from jsonb_array_elements(v_roster)e where e->>'id'=v_old_player_id limit 1),v_old_player_id), v_slot;
        end if;
      end if;
    end loop;
  end if;

  for v_slot, v_player_id in select key, value from jsonb_each_text(p_starters) loop
    select e->>'team' into v_team from jsonb_array_elements(v_roster)e where e->>'id'=v_player_id limit 1;
    select exists(
      select 1 from public.ball_knower_nfl_games g
      where g.season=v_season and g.week_number=p_week_number
        and (g.home_team=v_team or g.away_team=v_team) and g.kickoff_at<=now()
    ) into v_is_started;
    if v_is_started and (not v_has_existing or coalesce(v_existing.starters->>v_slot,'')<>v_player_id) then
      raise exception '% cannot be moved into the lineup after kickoff', coalesce((select e->>'name' from jsonb_array_elements(v_roster)e where e->>'id'=v_player_id limit 1),v_player_id);
    end if;
    if v_is_started and not exists(select 1 from jsonb_array_elements_text(v_locked)x where x=v_player_id) then
      v_locked := v_locked || to_jsonb(v_player_id);
    end if;
  end loop;

  insert into public.ball_knower_weekly_lineups(
    league_id,member_id,week_number,starters,bench,locked,locked_player_ids,submitted_at,updated_at
  ) values(
    p_league_id,v_member.id,p_week_number,p_starters,coalesce(p_bench,'[]'::jsonb),
    jsonb_array_length(v_locked)>=array_length(v_required_slots,1),v_locked,now(),now()
  )
  on conflict(league_id,member_id,week_number) do update set
    starters=excluded.starters,
    bench=excluded.bench,
    locked=excluded.locked,
    locked_player_ids=excluded.locked_player_ids,
    submitted_at=now(),
    updated_at=now()
  returning id into v_id;

  insert into public.ball_knower_transactions(league_id,member_id,transaction_type,summary,metadata)
  values(p_league_id,v_member.id,'lineup',v_member.user_name||' submitted Week '||p_week_number||' starters.',jsonb_build_object('week',p_week_number,'lockedPlayerIds',v_locked));
  return jsonb_build_object('id',v_id,'week',p_week_number,'memberId',v_member.id,'lockedPlayerIds',v_locked);
end;
$function$

CREATE OR REPLACE FUNCTION public.send_ball_knower_friend_request(p_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=ball_knower_private.require_permanent_community_user(); result uuid;
begin
  if p_user_id is null or p_user_id=me or not exists(select 1 from auth.users where id=p_user_id and not coalesce(is_anonymous,false)) then raise exception 'Choose a saved Ball Knower account'; end if;
  perform ball_knower_private.community_pair_lock(me,p_user_id);
  if exists(select 1 from public.ball_knower_user_blocks where (blocker_id=me and blocked_id=p_user_id) or (blocker_id=p_user_id and blocked_id=me)) then raise exception 'Friend request is unavailable'; end if;
  insert into public.ball_knower_friendships(requester_id,recipient_id) values(me,p_user_id)
  on conflict(least(requester_id,recipient_id),greatest(requester_id,recipient_id)) do update set updated_at=now()
  returning id into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.set_ball_knower_live_draft_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'UPDATE' and old.pick_index is distinct from new.pick_index then new.recovery_enabled:=true; end if;
  if new.status = 'active' and (tg_op = 'INSERT' or old.pick_index is distinct from new.pick_index or old.status is distinct from new.status or new.pick_deadline_at is null) then
    new.pick_started_at := clock_timestamp();
    new.pick_deadline_at := clock_timestamp() + make_interval(secs => new.pick_seconds);
  elsif new.status <> 'active' then
    new.pick_deadline_at := null;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_ball_knower_live_draft(p_league_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth uuid := (select auth.uid());
  v_league public.ball_knower_leagues%rowtype;
  v_order jsonb;
  v_member_count integer;
  v_human_count integer;
  v_ready_count integer;
  v_scheduled_at timestamptz;
  v_draft public.ball_knower_live_drafts%rowtype;
begin
  if v_auth is null then raise exception 'Authentication required'; end if;

  select * into v_league from public.ball_knower_leagues where id=p_league_id for update;
  if not found then raise exception 'League not found'; end if;
  if coalesce(v_league.settings->>'draftFormat','live_snake') in ('offline','mock','auction') then raise exception 'Use the selected draft format workspace instead of the live snake room';end if;
  if not exists(select 1 from public.ball_knower_league_members where league_id=p_league_id and auth_user_id=v_auth and is_ai=false) then raise exception 'Only league members can start the fantasy draft'; end if;
  if v_league.status<>'completed' or v_league.season_result is null then raise exception 'Lock the official draft order before starting the fantasy draft'; end if;

  v_scheduled_at:=nullif(v_league.settings->>'draftScheduledAt','')::timestamptz;
  if v_scheduled_at is not null and now()<v_scheduled_at then raise exception 'The fantasy draft is scheduled for %',v_scheduled_at; end if;

  select count(*) filter(where is_ai=false),count(*) filter(where is_ai=false and live_draft_ready=true),count(*)
  into v_human_count,v_ready_count,v_member_count
  from public.ball_knower_league_members where league_id=p_league_id;

  if v_human_count=1 and v_league.commissioner_auth_id=v_auth then
    update public.ball_knower_league_members set live_draft_ready=true
    where league_id=p_league_id and auth_user_id=v_auth and is_ai=false;
    v_ready_count:=1;
    update public.ball_knower_leagues
    set draft_countdown_started_at=coalesce(draft_countdown_started_at,now()-interval '30 seconds'),updated_at=now()
    where id=p_league_id returning * into v_league;
  end if;

  -- Unscheduled drafts retain the Ready + 30-second countdown flow. A scheduled
  -- draft starts at its saved instant whether or not every manager checked in.
  if v_scheduled_at is null then
    if v_human_count<1 or v_ready_count<>v_human_count then raise exception 'Every human manager must be ready before the fantasy draft starts'; end if;
    if v_league.draft_countdown_started_at is null then raise exception 'The 30-second draft countdown has not started'; end if;
    if now()<v_league.draft_countdown_started_at+interval '30 seconds' then raise exception 'The 30-second draft countdown is still running'; end if;
  elsif v_human_count<1 then
    raise exception 'At least one human manager is required';
  end if;

  select jsonb_agg(to_jsonb(pick->>'memberId') order by (pick->>'pickNumber')::integer)
  into v_order from jsonb_array_elements(coalesce(v_league.season_result->'draftOrder','[]'::jsonb)) pick;
  if v_order is null or jsonb_array_length(v_order)<>v_member_count or v_member_count<2 then raise exception 'The locked draft order does not match the league members'; end if;

  insert into public.ball_knower_live_drafts(league_id,status,order_member_ids,rounds,pick_index,picks,pick_seconds)
  values(p_league_id,'active',v_order,coalesce(nullif(v_league.settings->>'rosterSize','')::integer,15),0,'[]'::jsonb,case when coalesce(v_league.settings->>'draftFormat','live_snake')='autopick' then 15 else 60 end)
  on conflict(league_id) do nothing returning * into v_draft;
  if not found then select * into v_draft from public.ball_knower_live_drafts where league_id=p_league_id; end if;
  return to_jsonb(v_draft);
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_ball_knower_player_move(p_league_id text, p_player_snapshot jsonb, p_drop_player_id text DEFAULT NULL::text, p_faab_bid numeric DEFAULT 0, p_claim_order integer DEFAULT 1, p_claim_group_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_auth uuid:=auth.uid();
  v_member public.ball_knower_league_members%rowtype;
  v_settings jsonb;
  v_player_id text;
  v_active_waiver boolean;
  v_continuous boolean;
  v_claim_id uuid;
  v_process_at timestamptz;
  v_clears_at timestamptz;
  v_bid numeric:=round(greatest(0,coalesce(p_faab_bid,0)),2);
  v_group uuid:=coalesce(p_claim_group_id,gen_random_uuid());
  v_result jsonb;
begin
  if v_auth is null then raise exception 'Authentication required'; end if;
  v_player_id:=p_player_snapshot->>'id';
  if v_player_id is null or v_player_id='' then raise exception 'Player data is missing'; end if;

  perform pg_advisory_xact_lock(hashtext('bk-acquire-'||p_league_id||'-'||v_player_id));
  select * into v_member from public.ball_knower_league_members where league_id=p_league_id and auth_user_id=v_auth limit 1 for update;
  if not found then raise exception 'League membership not found'; end if;
  select settings into v_settings from public.ball_knower_leagues where id=p_league_id;
  if not found then raise exception 'League not found'; end if;

  if exists(
    select 1 from public.ball_knower_league_members m,
    jsonb_array_elements(coalesce(m.roster,'[]'::jsonb))e
    where m.league_id=p_league_id and e->>'id'=v_player_id
  ) then raise exception 'Player is no longer available'; end if;

  select w.clears_at into v_clears_at
  from public.ball_knower_player_waivers w
  where w.league_id=p_league_id and w.player_id=v_player_id
  for update;
  v_active_waiver:=found;

  -- A pending claim is authoritative even if an older/raw clears_at timestamp
  -- has elapsed. Never let an instant add jump claims waiting for the worker.
  if not v_active_waiver and exists(
    select 1 from public.ball_knower_waiver_claims wc
    where wc.league_id=p_league_id and wc.player_id=v_player_id and wc.status='pending'
  ) then
    v_active_waiver:=true;
  end if;

  v_continuous:=coalesce(v_settings->>'freeAgentMode','instant')='continuous';
  if not v_active_waiver and not v_continuous then
    v_result:=public.apply_ball_knower_player_move(p_league_id,v_member.id,p_player_snapshot,p_drop_player_id,0,'free_agent',null);
    return v_result||jsonb_build_object('status','added','message','Free agent added instantly after waivers cleared.');
  end if;

  if coalesce(v_settings->>'waiverType','priority')='faab' and v_bid>v_member.faab_balance then raise exception 'FAAB bid exceeds remaining budget'; end if;
  if exists(
    select 1 from public.ball_knower_waiver_claims
    where league_id=p_league_id and member_id=v_member.id and player_id=v_player_id and status='pending'
  ) then raise exception 'You already have a pending claim for this player'; end if;

  v_process_at:=case
    when v_clears_at is not null then public.next_ball_knower_waiver_run(v_settings,v_clears_at-interval '1 second')
    else public.next_ball_knower_waiver_run(v_settings,now())
  end;

  insert into public.ball_knower_waiver_claims(
    league_id,member_id,player_id,player_snapshot,drop_player_id,priority,faab_bid,claim_group_id,claim_order,process_at
  ) values(
    p_league_id,v_member.id,v_player_id,p_player_snapshot,p_drop_player_id,greatest(1,p_claim_order),v_bid,v_group,greatest(1,p_claim_order),v_process_at
  ) returning id into v_claim_id;

  return jsonb_build_object('status','pending','claimId',v_claim_id,'claimGroupId',v_group,'processAt',v_process_at,'message','Waiver claim scheduled.');
end;$function$
